+        (const __nv_bfloat16 *)kv->ptr, (float *)out->ptr, (const uint32_t *)positions->ptr,
+        nullptr, 0, rows, keys, heads, dim, ctx->scratch->ptr, ctx->scratch->bytes,
+        ctx->stream), "GLM VQ BF16 KV attention");
